import networkx as nx
import random

def find_graph():
    for _ in range(10000):
        G = nx.random_regular_graph(3, 26)
        # check girth
        # since we want girth >= 7, we can check if there are any cycles of length <= 6
        # an easy way is to check BFS from each node up to depth 3
        girth_ok = True
        for n in G.nodes():
            # BFS up to depth 3
            visited = {n: 0}
            queue = [n]
            parent = {n: None}
            while queue:
                curr = queue.pop(0)
                if visited[curr] == 3:
                    continue
                for neighbor in G.neighbors(curr):
                    if neighbor == parent[curr]:
                        continue
                    if neighbor in visited:
                        girth_ok = False
                        break
                    visited[neighbor] = visited[curr] + 1
                    parent[neighbor] = curr
                    queue.append(neighbor)
                if not girth_ok:
                    break
            if not girth_ok:
                break
        if girth_ok:
            return G
    return None

G = find_graph()
if G:
