    print(flat_edges)
else:
    print("Not found")

import random
import time

def solve():
    start_time = time.time()
    while time.time() - start_time < 45:
        adj = {i: set() for i in range(26)}
        edges = []

        def bfs_dist(u, v, limit):
            # return True if distance between u and v is <= limit
            if u == v: return True
            visited = {u}
            queue = [(u, 0)]
            while queue:
                curr, dist = queue.pop(0)
                if dist == limit:
                    continue
                for neighbor in adj[curr]:
                    if neighbor == v:
                        return True
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, dist + 1))
            return False

        # Try to add edges
        # We need sum of degrees to be between 26*3=78 and 26*4=104
        # Let's aim for 3-regular, so 39 edges.
        vertices = list(range(26))
        success = True
        for _ in range(39):
            # find valid pairs
            valid_pairs = []
            # To speed up, just pick random pairs and check
            # Or maintain a list of vertices with degree < 3
            available = [v for v in vertices if len(adj[v]) < 3]
            if not available:
                break

            # Try to find an edge
            edge_found = False
            random.shuffle(available)
            for u in available:
                for v in available:
                    if u >= v: continue
                    if v in adj[u]: continue
                    # check if adding (u,v) creates a cycle of length <= 6
                    # this happens if dist(u,v) <= 5 in the current graph
                    if not bfs_dist(u, v, 5):
                        adj[u].add(v)
                        adj[v].add(u)
                        edges.append((u, v))
                        edge_found = True
                        break
                if edge_found:
                    break
            if not edge_found:
                success = False
                break

        if success and all(len(adj[v]) >= 3 for v in vertices):
            return edges
    return None

